// Save to database via Sequelize bulkCreate (upsert)
const dbRecords = instruments.map(item => ({
  symbol: item.symbol,
  name: item.name,
  type: item.type,
  market: item.market || null,
  category: item.category || null,
  listing_date: item.listing_date || null,
  status: item.status || 'active'
}));

const BATCH_SIZE = 500;
let dbSaved = 0;
for (let i = 0; i < dbRecords.length; i += BATCH_SIZE) {
  const batch = dbRecords.slice(i, i + BATCH_SIZE);
  await Instrument.bulkCreate(batch, {
    updateOnDuplicate: ['name', 'type', 'market', 'category', 'listing_date', 'status', 'updated_at']
  });
  dbSaved += batch.length;
}
console.log(`✅ 成功持久化 ${dbSaved} 个标的到数据库`);

// Backup to file system
const fs = require('fs');
const path = require('path');
const dataDir = path.join(__dirname, '../../data');

try {
  if (!fs.existsSync(dataDir)) {
    fs.mkdirSync(dataDir, { recursive: true });
  }
  const filePath = path.join(dataDir, 'instruments.json');
  fs.writeFileSync(filePath, JSON.stringify({
    data: instruments,
    timestamp: Date.now(),
    count: instruments.length
  }, null, 2));
  console.log(`✅ 文件备份写入成功: ${filePath}`);
} catch (fileErr) {
  console.warn('⚠️ 文件备份写入失败（数据库已保存成功）:', fileErr.message);
}

